// Offline R30 candidate. Apply only after deriving one unchanged R25 178-mm side.
// Dimensions/recipe are generated by the same analytic build as the local STEP.
// Native regeneration, body identity mapping and native-vs-STEP check are pending.
function cp(context is Context,id is Id,body is Query,t is Transform) returns Query
{
 if(size(evaluateQuery(context,body))==0)return qNothing();
 opPattern(context,id,{"entities":body,"transforms":[t],"instanceNames":["copy"]});
 return qCreatedBy(id,EntityType.BODY);
}
function clone(context is Context,id is Id,body is Query) returns Query
{return cp(context,id,body,identityTransform());}
function combine(context is Context,id is Id,a is Query,b is Query,operation is BooleanOperationType) returns Query
{
 var countA=size(evaluateQuery(context,a));var countB=size(evaluateQuery(context,b));
 if(operation==BooleanOperationType.INTERSECTION && (countA==0 || countB==0))return qNothing();
 if(countA==0)return clone(context,id+"onlyB",b);
 if(countB==0)return clone(context,id+"onlyA",a);
 var aa=clone(context,id+"a",a);var bb=clone(context,id+"b",b);
 opBoolean(context,id+"op",{"tools":qUnion([aa,bb]),"operationType":operation});
 return qBodyType(qUnion([aa,bb,qCreatedBy(id+"op",EntityType.BODY)]),BodyType.SOLID);
}
function subtract(context is Context,id is Id,a is Query,b is Query) returns Query
{
 var aa=clone(context,id+"a",a);
 if(size(evaluateQuery(context,aa))==0 || size(evaluateQuery(context,b))==0)return aa;
 opBoolean(context,id+"op",{"targets":aa,"tools":b,"keepTools":true,"operationType":BooleanOperationType.SUBTRACTION});
 return qBodyType(qUnion([aa,qCreatedBy(id+"op",EntityType.BODY)]),BodyType.SOLID);
}
function keepMain(context is Context,id is Id,input is Query,limit is number) returns Query
{
 var qq=clone(context,id+"copy",input);var best=undefined;var maximum=0*millimeter^3;var total=0*millimeter^3;
 for(var b in evaluateQuery(context,qq)){var vol=evVolume(context,{"entities":b});total+=vol;if(vol>maximum){maximum=vol;best=b;}}
 if(best==undefined || (total-maximum)>limit*millimeter^3)throw regenError("Unexpected disconnected structural body: count " ~ size(evaluateQuery(context,qq)) ~ ", total " ~ total/millimeter^3 ~ ", largest " ~ maximum/millimeter^3 ~ ", allowed scrap " ~ limit);
 var scraps=qSubtraction(qq,best);if(size(evaluateQuery(context,scraps))>0)opDeleteBodies(context,id+"fragments",{"entities":scraps});return best;
}
function profile(context is Context,id is Id,pl is Plane,points is array) returns Query
{
 var sk=newSketchOnPlane(context,id,{"sketchPlane":pl});var pp=[];
 for(var p in points)pp=append(pp,vector(p[0],p[1])*millimeter);
 pp=append(pp,pp[0]);skPolyline(sk,"outline",{"points":pp});skSolve(sk);
 return qSketchRegion(id,false);
}
function prism(context is Context,id is Id,pl is Plane,pts is array,direction is Vector,depth is number) returns Query
{
 var q=profile(context,id+"s",pl,pts);
 opExtrude(context,id+"ex",{"entities":q,"direction":direction,"endBound":BoundingType.BLIND,"endDepth":depth*millimeter});
 opDeleteBodies(context,id+"ds",{"entities":qCreatedBy(id+"s",EntityType.BODY)});
 return qCreatedBy(id+"ex",EntityType.BODY);
}
function curvedProfile(context is Context,id is Id,pl is Plane,curves is array) returns Query
{
 var sk=newSketchOnPlane(context,id,{"sketchPlane":pl});
 for(var i=0;i<size(curves);i+=1){var c=curves[i];
 if(size(c)==2)skLineSegment(sk,"line"~i,{"start":vector(c[0][0],c[0][1])*millimeter,"end":vector(c[1][0],c[1][1])*millimeter});
 else skArc(sk,"arc"~i,{"start":vector(c[0][0],c[0][1])*millimeter,"mid":vector(c[1][0],c[1][1])*millimeter,"end":vector(c[2][0],c[2][1])*millimeter});
 }
 skSolve(sk);return qSketchRegion(id,false);
}
function roundBody(context is Context,id is Id,origin is Vector,normal is Vector,r0 is number,r1 is number,depth is number) returns Query
{
 var qq=[];var ss=[];
 for(var i=0;i<2;i+=1){var sid=id+("s"~i);var sk=newSketchOnPlane(context,sid,{"sketchPlane":plane((origin+normal*depth*i)*millimeter,normal)});
 skCircle(sk,"circle",{"center":vector(0,0)*millimeter,"radius":(i==0?r0:r1)*millimeter});skSolve(sk);qq=append(qq,qSketchRegion(sid,false));ss=append(ss,qCreatedBy(sid,EntityType.BODY));}
 opLoft(context,id+"loft",{"profileSubqueries":qq});opDeleteBodies(context,id+"ds",{"entities":qUnion(ss)});
 return qCreatedBy(id+"loft",EntityType.BODY);
}

